<!doctype html><html><head><meta charset="utf-8"><title>Payment invoice {{ $payment->id }}</title><style>body{font-family:Arial,sans-serif;color:#172033;margin:36px}.head{display:flex;justify-content:space-between;border-bottom:3px solid #1976ed;padding-bottom:18px}h1{margin:0;color:#1976ed}.meta{margin:28px 0;display:grid;grid-template-columns:1fr 1fr;gap:12px}.box{border:1px solid #dce4ef;border-radius:8px;padding:16px}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #dce4ef;text-align:left}.total{font-size:20px;font-weight:700;text-align:right;margin-top:20px}@media print{button{display:none}body{margin:12mm}}</style></head><body><button onclick="print()">Print</button><div class="head"><div><h1>PAYMENT INVOICE</h1><div>{{ config('app.name') }}</div></div><strong>{{ $payment->invoice?->number ?? ('PAY-'.str_pad((string)$payment->id,6,'0',STR_PAD_LEFT)) }}</strong></div><div class="meta"><div class="box"><strong>Customer</strong><br>{{ $payment->user?->name }}<br>{{ $payment->user?->email }}</div><div class="box"><strong>Payment details</strong><br>Date: {{ ($payment->paid_at ?? $payment->created_at)->format('Y-m-d H:i:s') }}<br>Method: {{ $payment->gateway?->name ?? 'Payment' }}<br>Reference: {{ $payment->external_id ?: $payment->uuid }}</div></div><table><thead><tr><th>Description</th><th>Amount</th><th>Fee</th><th>Total paid</th></tr></thead><tbody><tr><td>Account balance payment</td><td>{{ number_format((float)$payment->amount_base,2) }}</td><td>{{ number_format((float)$payment->fee_base,2) }}</td><td>{{ number_format((float)$payment->payable_base,2) }} {{ $payment->currency_code }}</td></tr></tbody></table><div class="total">Paid: {{ number_format((float)$payment->payable_base,2) }} {{ $payment->currency_code }}</div></body></html>
